-- Indonesia: milestones + English translations. Hand-written, following
-- the Hungary pattern. Six milestones, live-researched against
-- vatcalc.com, fiscal-requirements.com, hanumaglobal.com, muc.co.id
-- (PER-11/PJ/2025), and DJP's own site (pajak.go.id):
--
-- 1. id-efaktur-mandatory-2014 (2014-04-01, anchor, off-board,
--    mandate_scope='b2b') -- e-Faktur Pajak (electronic VAT invoice)
--    becomes mandatory for a first, DJP-designated group of taxpayers.
--    The origin of Indonesia's e-invoicing mandate.
-- 2. id-efaktur-java-bali-2015 (2015-07-01, off-board, mandate_scope=
--    'b2b') -- e-Faktur extends to all VAT-registered taxpayers (PKP) in
--    Java and Bali, Indonesia's most commercially dense regions.
-- 3. id-efaktur-nationwide-2016 (2016-07-01, on-board, mandate_scope=
--    'b2b') -- e-Faktur becomes mandatory for every PKP nationwide,
--    completing the phased rollout. Indonesia's foundational, economy-
--    wide e-invoicing mandate -- the flagship entry until Coretax.
-- 4. id-coretax-launch-2025 (2025-01-01, on-board, mandate_scope='b2b')
--    -- DJP launches Coretax, its new unified platform intended to
--    replace e-Faktur. Early rollout issues led to KEP-54/PJ/2025 (12
--    Feb 2025) reopening e-Faktur Client Desktop as a fallback.
-- 5. id-per11-upload-deadline-2025 (2025-05-22, on-board, mandate_scope=
--    'b2b') -- PER-11/PJ/2025 moves the Coretax invoice upload deadline
--    from the 15th to the 20th of the following month, with real
--    consequences: a late upload costs the buyer their VAT input credit.
-- 6. id-coretax-full-enforcement-2025 (2025-12-31, on-board,
--    mandate_scope='b2b') -- Coretax becomes fully enforced nationwide:
--    DJP clearance becomes a legal precondition for a valid invoice for
--    the first time, a genuine shift from e-Faktur's old post-creation
--    validation model. This is the headline current-news milestone.
--    The secondary-sourced claim that Coretax becomes the "primary VAT
--    operations interface" from 1 January 2026 is folded into this
--    milestone's description rather than given its own row, since it
--    is less firmly confirmed than the 31 December 2025 enforcement
--    date itself.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'id-efaktur-mandatory-2014', id, '2014-04-01', 1, 'https://www.vatcalc.com/indonesia/indonesia-e-factur-pajak-electronic-invoicing/', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'ID';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-mandatory-2014', 'en', 'e-Faktur Pajak (electronic VAT invoice) launches for designated taxpayers', 'From 1 April 2014, Indonesia''s Directorate General of Taxes (DJP) required a first group of designated VAT-registered taxpayers (Pengusaha Kena Pajak, PKP) to issue e-Faktur Pajak -- an electronic value-added tax invoice -- rather than paper invoices. This was the origin of Indonesia''s long-running move toward mandatory e-invoicing, though at this stage the requirement applied only to a limited set of taxpayers designated by DJP, not the whole VAT-registered population.', '["No action required for this historical milestone -- included for context ahead of the entries below", "If you''re a PKP that predates Indonesia''s e-invoicing rollout, note the requirement widened in stages through 2015 and 2016 -- see the following milestones"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'id-efaktur-java-bali-2015', id, '2015-07-01', 0, 'https://hanumaglobal.com/mandates/indonesia', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'ID';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-java-bali-2015', 'en', 'e-Faktur becomes mandatory for taxpayers in Java and Bali', 'From 1 July 2015, DJP extended the e-Faktur Pajak requirement to all VAT-registered taxpayers (PKP) located in Java and Bali -- Indonesia''s most commercially dense regions -- well beyond the narrow set of designated taxpayers covered from 2014. Businesses outside Java and Bali remained on paper or manual invoicing for one more year.', '["PKP based in Java or Bali should confirm their invoicing process fully switched to e-Faktur from this date if it hasn''t already", "Businesses expanding into Java or Bali should budget for e-Faktur compliance immediately, not on the later nationwide timeline"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'id-efaktur-nationwide-2016', id, '2016-07-01', 0, 'https://www.vatcalc.com/indonesia/indonesia-e-factur-pajak-electronic-invoicing/', 1, '[{"label": "Direktorat Jenderal Pajak (DJP)", "url": "https://www.pajak.go.id/"}]', NULL, 'b2b' FROM countries WHERE code = 'ID';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-efaktur-nationwide-2016', 'en', 'e-Faktur becomes mandatory nationwide for all VAT-registered taxpayers', 'From 1 July 2016, e-Faktur Pajak became mandatory for every VAT-registered taxpayer (PKP) in Indonesia, completing the phased rollout that began in 2014. From this date, paper VAT invoices were no longer acceptable anywhere in the country -- every PKP had to issue electronic tax invoices, validated after creation and assigned a Tax Invoice Serial Number (Nomor Seri Faktur Pajak, NSFP). This is the foundational, economy-wide e-invoicing mandate that Indonesia''s current Coretax platform (from 2025) has since replaced with a real-time clearance model.', '["Confirm your invoicing system still issues valid e-Faktur documents with a correctly formatted NSFP", "If your business only recently registered as a PKP, confirm your onboarding included e-Faktur setup rather than relying on paper invoicing"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'id-coretax-launch-2025', id, '2025-01-01', 0, 'https://hanumaglobal.com/mandates/indonesia', 1, '[{"label": "Coretax DJP", "url": "https://coretaxdjp.pajak.go.id/"}]', NULL, 'b2b' FROM countries WHERE code = 'ID';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-launch-2025', 'en', 'Coretax launches, beginning DJP''s move from e-Faktur to a unified tax platform', 'On 1 January 2025, Indonesia''s Directorate General of Taxes (DJP) launched Coretax, a new administration platform intended to eventually replace e-Faktur and unify VAT invoicing, filing, and payment in one system. Early rollout brought technical issues significant enough that DJP reopened the legacy e-Faktur Client Desktop as a fallback channel via decree KEP-54/PJ/2025 (12 February 2025). Coretax auto-generates each invoice''s NSFP serial number and moved Indonesia toward a genuine real-time validation model rather than e-Faktur''s older post-creation checks.', '["If you''re still using e-Faktur Client Desktop as a fallback, plan your transition to Coretax well before the 31 December 2025 enforcement date", "Test your invoicing/accounting software''s Coretax integration (web portal, desktop client, or Host-to-Host) ahead of full enforcement rather than during it"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'id-per11-upload-deadline-2025', id, '2025-05-22', 0, 'https://muc.co.id/en/article/key-highlights-of-per-11pj2025', 1, '[{"label": "Coretax DJP", "url": "https://coretaxdjp.pajak.go.id/"}]', NULL, 'b2b' FROM countries WHERE code = 'ID';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-per11-upload-deadline-2025', 'en', 'PER-11/PJ/2025 moves the invoice upload deadline to the 20th of the following month', 'DJP regulation PER-11/PJ/2025, issued 22 May 2025, changed the deadline for uploading tax invoices to Coretax from the 15th to the 20th of the month following issuance, and revised serial and transaction code rules for invoices processed through the platform. A related regulation, PER-8/PJ/2025, was coordinated alongside it. Missing the 20th-of-the-month deadline means the buyer loses eligibility to claim VAT input tax credit on that invoice -- a real, immediate compliance consequence, not just a procedural formality.', '["Update your invoicing calendar to the 20th-of-the-following-month Coretax upload deadline, not the earlier 15th-of-the-month date it replaced", "Confirm your accounts-payable team understands that a late-uploaded supplier invoice can cost your business its VAT input credit"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'id-coretax-full-enforcement-2025', id, '2025-12-31', 0, 'https://www.fiscal-requirements.com/news/4767-indonesia-coretax-e-invoicing-mandatory-for-all-vat-registered-taxpayers-by-end-of-2025', 1, '[{"label": "Coretax DJP", "url": "https://coretaxdjp.pajak.go.id/"}]', NULL, 'b2b' FROM countries WHERE code = 'ID';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('id-coretax-full-enforcement-2025', 'en', 'Coretax becomes fully enforced -- DJP clearance becomes a legal precondition for invoice issuance', 'From 31 December 2025, Coretax became fully enforced nationwide for nearly all VAT-registered taxpayers (PKP), marking a genuine shift to a clearance model: DJP approval is now a legal precondition for a tax invoice to be valid, not a post-creation check as under the old e-Faktur system. Invoices lacking DJP clearance cannot support the buyer''s VAT input tax deduction. Large taxpayers may continue using e-Faktur Desktop or Host-to-Host (H2H) integration channels, but those channels now feed into Coretax''s real-time validation rather than operating independently. Some secondary sources describe Coretax becoming the primary interface for all VAT operations from 1 January 2026, immediately following full enforcement -- treat that specific framing as less firmly confirmed than the 31 December 2025 enforcement date itself.', '["Confirm your invoicing workflow issues invoices through a Coretax-connected channel (web portal, desktop client, or H2H) rather than any standalone legacy system", "Build in a real-time DJP-clearance check before treating any invoice as final -- an uncleared invoice is not legally valid under the new model"]');
